export function deepClone(value){return typeof structuredClone==="function"?structuredClone(value):JSON.parse(JSON.stringify(value));}
export function pad3(value){return String(value).padStart(3,"0");}
export function isoDate(value=new Date()){return value.toISOString().slice(0,10);}
export function safeId(value){return String(value||"").trim().replace(/[^A-Za-z0-9._-]+/g,"-").replace(/^-+|-+$/g,"")||"UNKNOWN";}
export function makeJobId(value=new Date()){
  const stamp=value.toISOString().replace(/\D/g,"").slice(0,14);
  const random=globalThis.crypto?.getRandomValues?Array.from(globalThis.crypto.getRandomValues(new Uint8Array(3)),b=>b.toString(16).padStart(2,"0")).join("").toUpperCase():"000000";
  return `JOB-${stamp}-${random}`;
}
export function artifactFilename(jobId,artifactType,version,extension,date=new Date()){
  const ext=String(extension||"json").replace(/^\./,"");
  return `${safeId(jobId)}__${safeId(artifactType).toUpperCase()}__${version}__${isoDate(date)}.${ext}`;
}
export async function sha256Bytes(bytes){
  const view=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes);
  const digest=await globalThis.crypto.subtle.digest("SHA-256",view);
  return Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,"0")).join("");
}
export async function sha256Text(text){return sha256Bytes(new TextEncoder().encode(String(text)));}
export function nextVersion(records){return `v${pad3((records?.length||0)+1)}`;}
export function normalizeOuterQuotes(value){const s=String(value||"").trim();return /^[“"].*[”"]$/s.test(s)?s.slice(1,-1).trim():s;}
export function recordControlKey(text){
  const value=String(text||"").replace(/<<[^>]+>>/g,"").replace(/[“”"]/g,"").trim();
  const first=value.split(/\s*\/\s*|\s*:\s*/)[0].trim();
  return first.replace(/\s+/g," ").slice(0,100);
}
export function createRecordTemplate(stage){
  const lines=[`STAGE ${String(stage.number).padStart(2,"0")} ${stage.title}`,""];
  for(const control of stage.controls){
    lines.push(`CONTROL_ID: ${control.id}`);
    lines.push(`REQUIRED_CONTROL: ${control.text}`);
    lines.push("VALUE_OR_EVIDENCE: <<ENTER>>","");
  }
  lines.push("STAGE_DECISION: <<READY TO PROCEED / BLOCKED / NOT READY - CORRECTION REQUIRED>>");
  lines.push("DECISION_EVIDENCE: <<ENTER>>");
  lines.push("NEXT_STAGE_OR_RETURN_STAGE: <<ENTER>>");
  lines.push("DECIDED_BY: <<ENTER>>");
  lines.push("DATE_AND_TIME: <<ENTER>>");
  return lines.join("\n");
}
export function createAppendixTemplate(letter){
  const spec=APPENDICES[letter];
  return spec.fields.map(field=>{
    if(field==="OLD_BASELINE_STATUS_CARRIED_FORWARD"||field==="OLD_RELEASE_DECISION_CARRIED_FORWARD")return `${field}: FALSE`;
    if(field==="NEW_JOB_START_STAGE")return `${field}: STAGE 01`;
    if(field==="NEW_WORKBOOK_VERSION")return `${field}: v001`;
    return `${field}: <<ENTER>>`;
  }).join("\n");
}
