function renderAppendix(letter){activeAppendix=letter;state.activeAppendix=letter;nav.innerHTML=Object.entries(APPENDICES).map(([k,s])=>`<button data-letter="${k}" class="${k===letter?"active":""}">${k} ${esc(s.title)}</button>`).join("");nav.querySelectorAll('[data-letter]').forEach(b=>b.addEventListener('click',()=>{activeAppendix=b.dataset.letter;renderAppendix(activeAppendix);}));const spec=APPENDICES[letter],store=state.appendices[letter];content.innerHTML=`${runtimeMessage()}<div class="card"><h2>APPENDIX ${letter} - ${esc(spec.title)}</h2><h3>CHECKLIST</h3>${spec.checklist.map(x=>`<label><input type="checkbox"> ${esc(x)}</label>`).join("")}<h3>APPEND-ONLY RECORD</h3><textarea id="appendixDraft" class="record">${esc(store.draft)}</textarea><button id="prefillAppendix">Prefill current stage/job</button> <button id="hashAppendix">SHA-256 draft</button> <button id="saveAppendix" class="primary">Append immutable record</button><div id="appendixHash" class="muted"></div><h3>IMMUTABLE HISTORY</h3>${store.records.length?store.records.slice().reverse().map(r=>`<div class="card"><b>${esc(r.id)} ${esc(r.version)}</b><div class="muted">${esc(r.sha256)} • ${esc(r.createdAt)}</div><pre class="copy">${esc(r.text)}</pre></div>`).join(""):`<p class="muted">No records saved.</p>`}</div>`;byId("appendixDraft").addEventListener("input",e=>{store.draft=e.target.value;saveState();});byId("prefillAppendix").addEventListener("click",()=>prefillAppendix(letter));byId("hashAppendix").addEventListener("click",async()=>byId("appendixHash").textContent=await sha256Text(byId("appendixDraft").value));byId("saveAppendix").addEventListener("click",()=>saveAppendixRecord(letter));}
function releaseIdentityMarkup(){const release=state.release,latest=release.comparisons.at(-1),list=(items,label)=>`<h3>${label}</h3>${items.length?items.map(f=>`<div class="card"><b>${esc(f.name)}</b><div class="muted">${f.size} bytes • ${esc(f.sha256)}</div></div>`).join(""):`<p class="muted">No files hashed.</p>`}`;return `<h3>RELEASE IDENTITY</h3><p class="muted">Audited files and delivery files are selected and hashed independently.</p><label>Files that completed final audit<input id="auditedFilesInput" type="file" multiple></label><label>Exact files selected for delivery<input id="releaseFilesInput" type="file" multiple></label><button id="hashAudited">Hash audited files</button> <button id="hashRelease">Rehash delivery files now</button> <button id="compareRelease">Compare and apply delivery stop</button>${list(release.auditedDraft,"AUDITED ARTIFACTS")}${list(release.releaseDraft,"IMMEDIATE PRE-DELIVERY REHASH")}${latest?`<pre class="copy">${esc(JSON.stringify(latest,null,2))}</pre>`:""}<p><b>DELIVERY AUTHORIZATION: ${esc(release.authorization)}</b></p>`;}
function bindReleaseIdentity(){byId("auditedFilesInput").addEventListener("change",e=>pendingAuditedFiles=Array.from(e.target.files||[]));byId("releaseFilesInput").addEventListener("change",e=>pendingReleaseFiles=Array.from(e.target.files||[]));byId("hashAudited").addEventListener("click",async()=>{state.release.auditedDraft=await hashFiles(pendingAuditedFiles);state.release.auditedDraft.forEach((f,i)=>f.artifactId=`ARTIFACT-${String(i+1).padStart(3,"0")}`);state.release.authorization="NOT AUTHORIZED";saveState();renderStage(28);});byId("hashRelease").addEventListener("click",async()=>{state.release.releaseDraft=await hashFiles(pendingReleaseFiles);state.release.authorization="NOT AUTHORIZED";saveState();renderStage(28);});byId("compareRelease").addEventListener("click",async()=>{const result=compareArtifactSets(state.release.auditedDraft,state.release.releaseDraft,state.release.gateState);result.hashAuditId=`HASH-AUDIT-${pad3(state.release.comparisons.length+1)}`;result.createdAt=new Date().toISOString();result.sha256=await sha256Text(JSON.stringify(result));state.release.comparisons.push(Object.freeze(result));state.release.authorization=result.authorization;state.release.authorizedArtifactIds=result.authorization==="AUTHORIZED"?result.comparisons.map(x=>x.artifactId):[];saveState();renderStage(28);});}
async function saveJobRevision(){if(!state.job.JOB_ID.trim()||!state.job.EXACT_USER_OBJECTIVE_VERBATIM.trim()){setMessage("JOB_ID and EXACT_USER_OBJECTIVE_VERBATIM are required.");return;}const payload=deepClone(state.job),result=await immutableRevision(state.jobRevisions,payload,{artifactType:"JOB-CONTROL"});if(!result.changed){setMessage("Job control unchanged; existing immutable revision remains authoritative.");return;}const prior=state.jobRevisions.at(-1);state.jobRevisions.push(result.record);if(prior){const changeId=`CHANGE-AUTO-${Date.now()}`,invalidated=invalidateDownstream(state,0,changeId);await appendAutomaticChange({changeId,trigger:"JOB CONTROL CHANGE",artifactId:"MASTER-JOB-CONTROL",oldVersion:prior.version,oldSha:prior.sha256,newVersion:result.record.version,newSha:result.record.sha256,invalidated});}saveState();downloadText(artifactFilename(state.job.JOB_ID,"JOB-CONTROL",result.record.version,"json"),JSON.stringify(result.record,null,2),"application/json");renderControl();setMessage(`Immutable job-control revision ${result.record.version} saved.`);}
function renderControl(){nav.innerHTML="";const fields=JOB_FIELDS.map(field=>`<label>${esc(field)}${JOB_TEXTAREA_FIELDS.has(field)?`<textarea data-job="${field}">${esc(state.job[field]||"")}</textarea>`:`<input data-job="${field}" value="${esc(state.job[field]||"")}">`}</label>`).join("");const folderText=[`${safeId(state.job.JOB_ID||"JOB_ID")}/`,...FOLDERS.map(f=>`  ${f}/`)].join("\n");content.innerHTML=`${runtimeMessage()}<div class="card"><h2>MASTER JOB CONTROL</h2>${fields}<button id="saveJobControl" class="primary">Save immutable job-control revision</button><h3>SUPPORTING OUTPUTS</h3><button id="downloadPrompts">Download prompts-only TXT</button> <button id="folderManifest">Download folder manifest</button><h3>PLACEHOLDER AND OUTCOME RULES</h3><p>UNKNOWN = fact not established. NONE = evidence establishes no item exists. NOT APPLICABLE = objective applicability rule excludes the field.</p><p>Requirement outcomes: ${REQUIREMENT_OUTCOMES.join(" | ")}<br>Release outcomes: ${RELEASE_OUTCOMES.join(" | ")}</p><h3>MANDATORY OPERATING RULES</h3><ul>${UNIVERSAL_RULES.map(r=>`<li>${esc(r)}</li>`).join("")}</ul><h3>AGENT-ROLE SEPARATION MAP</h3><ul>${ROLE_SEPARATION.map(r=>`<li>${esc(r)}</li>`).join("")}</ul><h3>PHONE FOLDER STRUCTURE</h3><pre class="copy">${esc(folderText)}</pre><h3>IMMUTABLE HISTORY</h3><p class="muted">${state.jobRevisions.length} job-control revisions • ${Object.values(state.stages).reduce((n,s)=>n+s.revisions.length,0)} stage revisions • ${Object.values(state.appendices).reduce((n,a)=>n+a.records.length,0)} appendix/control records • ${archiveList().length} preserved archives.</p></div>`;content.querySelectorAll('[data-job]').forEach(el=>el.addEventListener('input',e=>{state.job[e.target.dataset.job]=e.target.value;saveState();}));byId("saveJobControl").addEventListener("click",saveJobRevision);byId("downloadPrompts").addEventListener("click",downloadPrompts);byId("folderManifest").addEventListener("click",()=>downloadText(artifactFilename(state.job.JOB_ID||"JOB_ID","FOLDER-MANIFEST","v001","txt"),folderManifestText()));}
